/* ---------- the live preset ---------- */
/* The active preset's values as plain bindings, so the analysis below reads XL
   and CAL exactly as it did when they were constants. The functions that do
   the work were not touched when presets came in (2026-09-26), which is what
   makes "the sweep reads identically, to the last digit" a real check of the
   move. Assigned only by usePreset(). */
const PRESET_KEYS=['XL','XR','AX1','AX2','YTOP','YBOT','RY1','RY2','BASE_TILT',
  'CAL','Y_CAL_MIN','Y_CAL_MAX','Y_MAX_STATE','LOW_FLOW','LOW_LABEL','LOW_REASON','MAX_REASON',
  'MAX_LABEL','MAX_UNIT','VIEW_X','VIEW_W','VIEW_Y','VIEW_H','KNOB','BACKLASH'];
let PRESET=null;
let KNOB_ERROR=null;   // why the live preset's knob table was set aside, if it was
let XL, XR, AX1, AX2, YTOP, YBOT, RY1, RY2, BASE_TILT,
    CAL, Y_CAL_MIN, Y_CAL_MAX, Y_MAX_STATE, LOW_FLOW, LOW_LABEL, LOW_REASON, MAX_REASON,
    MAX_LABEL, MAX_UNIT, VIEW_X, VIEW_W, VIEW_Y, VIEW_H, KNOB, BACKLASH;
/* References are built per preset and kept, so the admin page can move between
   frames from two machines without rebuilding them each time. */
const REF_CACHE={};
let REFS=[];
function usePreset(id){
  const p=Object.prototype.hasOwnProperty.call(PRESETS,id) ? PRESETS[id] : null;
  if(!p) throw new Error('Unknown concentrator preset: '+id);
  /* Every key, and nothing but the keys: a misspelt field in a new preset would
     otherwise leave its binding undefined, and undefined compares false against
     everything — which is how a quality gate once stopped rejecting anything
     (T.kontrast, 2026-08-15). */
  const extra=Object.keys(p).filter(k=>k!=='name'&&k!=='refs'&&!PRESET_KEYS.includes(k));
  const missing=PRESET_KEYS.filter(k=>!(k in p));
  if(extra.length||missing.length)
    throw new Error('Preset '+id+': unknown '+extra.join(',')+' missing '+missing.join(','));
  /* Present is not enough once the preset claims a calibration. null compares
     as 0, so a LOW_FLOW left null would make "r.flow < LOW_FLOW" never true and
     a switched-off machine would print 0.2 instead of the bottom state — the
     same silent failure as undefined, one step removed. Only the display crop
     may stay null: the device page then shows the whole frame. */
  if(p.CAL){
    // The display crop and the knob table are optional: without them the
    // page shows the whole frame, and degree buttons.
    const unset=PRESET_KEYS.filter(k=>!k.startsWith('VIEW_')&&k!=='KNOB'&&k!=='BACKLASH'&&p[k]==null);
    if(unset.length||!p.refs().length)
      throw new Error('Preset '+id+' has a curve but is incomplete: '+
                      (unset.length?'unset '+unset.join(','):'no references'));
  }
  // A knob table turns the motor from her page: it must be whole, whether or
  // not the preset has a curve yet. At least two rows, strictly rising in both
  // flow and degrees (equal flows would divide by zero in knobDeg), and the
  // backlash that goes with it.
  // A table that is not whole disables the flow buttons, NOT the reading: a
  // table exists only to add buttons, and must never take the number away.
  KNOB_ERROR=null;
  if(p.KNOB!=null){
    const k=p.KNOB, okRows=Array.isArray(k) && k.length>=2 &&
      k.every((r,i)=>Array.isArray(r) && r.length===2 && Number.isFinite(r[0]) && Number.isFinite(r[1]) &&
                     (i===0 || (r[0]>k[i-1][0] && r[1]>k[i-1][1])));
    if(!okRows) KNOB_ERROR='Preset '+id+': KNOB must be rows [L/min, degrees], both strictly rising';
    else if(!(Number.isFinite(p.BACKLASH) && p.BACKLASH>=0)) KNOB_ERROR='Preset '+id+': KNOB without a BACKLASH';
  }
  ({XL, XR, AX1, AX2, YTOP, YBOT, RY1, RY2, BASE_TILT,
    CAL, Y_CAL_MIN, Y_CAL_MAX, Y_MAX_STATE, LOW_FLOW, LOW_LABEL, LOW_REASON, MAX_REASON,
    MAX_LABEL, MAX_UNIT, VIEW_X, VIEW_W, VIEW_Y, VIEW_H, KNOB, BACKLASH}=p);
  if(KNOB_ERROR){ KNOB=null; BACKLASH=null; if(typeof console!=='undefined') console.warn(KNOB_ERROR); }
  PRESET=id;
  REFS=REF_CACHE[id]||[];
}
/* ---------- flow steps on her page ----------
   How far to turn the knob to change the flow by `delta` L/min from `flow`,
   from the live preset's measured KNOB table. The target is clamped to the
   range the table covers AND to 1..9 L/min — never above 9, never below 1, so
   at 8.2 a "+2" turns only to the top. `lastOp` is the direction the knob
   was last turned, as the DEVICE reports it (any page, any phone; a turn by
   hand it cannot know): the backlash is paid only when turning the other
   way, and not when it is unknown — turning a little short is the
   safe error, turning too far is not, which is also why degrees round down.
   Returns {op, deg, target, from} or null: no table, or a flow outside what
   the table covers, is no promise at all — the page then offers the fixed
   degree buttons instead. deg can exceed one press (180°); the caller splits. */
function knobDeg(f){
  for(let i=1;i<KNOB.length;i++){
    const [f0,d0]=KNOB[i-1], [f1,d1]=KNOB[i];
    if(f>=f0 && f<=f1) return d0+(d1-d0)*(f-f0)/(f1-f0);
  }
  return null;
}
/* The inverse: the flow at `d` degrees on the table, or null off its ends. */
function knobFlowAt(d){
  for(let i=1;i<KNOB.length;i++){
    const [f0,d0]=KNOB[i-1], [f1,d1]=KNOB[i];
    if(d>=d0 && d<=d1) return f0+(f1-f0)*(d-d0)/(d1-d0);
  }
  return null;
}
/* The range the buttons act on: the measured table, inside 1..9 L/min. */
function knobRange(){
  if(!KNOB || KNOB.length<2) return null;
  return {lo:Math.max(1.0, KNOB[0][0]), hi:Math.min(9.0, KNOB[KNOB.length-1][0])};
}
/* Is `flow` something the buttons can step from? `margin` lets a page that
   is already showing the flow buttons keep them while the ball bobs just past
   an end of the table — without it the two button sets would swap every
   second at 1.0 and at the top. Past an end, knobPlan steps from the end
   itself: the turn comes out short, never long. */
function knobCovers(flow, margin){
  const r=knobRange();
  return !!r && Number.isFinite(flow) && flow>=r.lo-(margin||0) && flow<=r.hi+(margin||0);
}
function knobPlan(flow, delta, lastOp, margin){
  if(!knobCovers(flow, margin) || !Number.isFinite(delta) || delta===0) return null;
  const {lo, hi}=knobRange();
  const from=Math.min(hi, Math.max(lo, flow));
  // From the clamped start: past an end the step is sized from the end, so
  // 9.0 -0,2 turns what 8.8 -> 8.6 needs, and lands near 8.8.
  const target=Math.min(hi, Math.max(lo, from+delta));
  const op = delta>0 ? 'plus' : 'minus';
  let deg=Math.abs(knobDeg(target)-knobDeg(from));
  // Clamped to where it already is: at the limit, and nothing to turn. "Nothing"
  // includes a turn under the motor's 4° when the target IS the limit: from
  // 1.01 a "-1" is not a step too small to make, it is already at the bottom.
  if(Math.abs(target-from)<0.01 || (deg<4 && (target===lo || target===hi)))
    return {op, deg:0, target, from, lo, hi, atLimit:true};
  /* The slack, on a reversal — but only if the turn would stay inside lo..hi
     even with NO slack to take up. The device knows its own last direction,
     not a hand on the knob: turned by hand the other way, the slack is
     already taken and the extra degrees move the ball. Measured 2026-09-29
     with the 21° slack: from 1.2, "-0,2" after a hand turn down would land
     under 1, where the Platinum alarms. There the slack is left out and the
     step comes out short, which is the safe error. */
  if(lastOp && lastOp!==op && BACKLASH>0){
    const land=knobFlowAt(knobDeg(from) + (op==='plus' ? 1 : -1)*(deg+BACKLASH));
    if(land!==null && land>=lo && land<=hi) deg+=BACKLASH;
  }
  // Round down: short is the safe error. Under 4° the caller turns nothing.
  return {op, deg:Math.floor(deg), target, from, lo, hi, atLimit:false};
}

/* A preset without a curve has not been calibrated yet. */
const isCalibrated=(id)=>!!(Object.prototype.hasOwnProperty.call(PRESETS,id)&&PRESETS[id].CAL);
/* True once the live preset's references are built (an uncalibrated preset has
   none, and is ready at once: it can only refuse). */
const refsReady=()=>PRESET!==null&&REF_CACHE[PRESET]!==undefined;

/* ---------- image helpers ---------- */
function toGray(imgData){
  const d=imgData.data, g=new Float32Array(W*H);
  for(let i=0,j=0;i<g.length;i++,j+=4)
    g[i]=0.299*d[j]+0.587*d[j+1]+0.114*d[j+2];
  return g;
}
function boxH(src,dst,r){
  const win=2*r+1;
  for(let y=0;y<H;y++){
    const o=y*W; let sum=0;
    for(let x=-r;x<=r;x++) sum+=src[o+Math.min(W-1,Math.max(0,x))];
    for(let x=0;x<W;x++){
      dst[o+x]=sum/win;
      sum-=src[o+Math.min(W-1,Math.max(0,x-r))];
      sum+=src[o+Math.min(W-1,Math.max(0,x+r+1))];
    }
  }
}
function boxV(src,dst,r){
  const win=2*r+1;
  for(let x=0;x<W;x++){
    let sum=0;
    for(let y=-r;y<=r;y++) sum+=src[Math.min(H-1,Math.max(0,y))*W+x];
    for(let y=0;y<H;y++){
      dst[y*W+x]=sum/win;
      sum-=src[Math.min(H-1,Math.max(0,y-r))*W+x];
      sum+=src[Math.min(H-1,Math.max(0,y+r+1))*W+x];
    }
  }
}
function flatfield(g){
  const r=Math.floor(BOXW/2);
  let a=Float32Array.from(g), b=new Float32Array(W*H);
  for(let p=0;p<PASSES;p++){ boxH(a,b,r); boxV(b,a,r); }
  const out=new Float32Array(W*H);
  for(let i=0;i<out.length;i++) out[i]=g[i]/Math.max(a[i],1e-6);
  return out;
}
/* The x window slides with the row, so a tilted tube is still sampled down
   its middle. tilt is tan(angle); over 550 rows 2 degrees is 19 px, enough
   to smear an untilted band across the tube wall. */
function bandProfile(ff,x1,x2,tilt){
  const p=new Float32Array(H), n=x2-x1, t=tilt||0;
  for(let y=0;y<H;y++){
    const off=Math.round(t*(y-H/2));
    let s=0;
    for(let x=x1+off;x<x2+off;x++) s+=ff[y*W+Math.min(W-1,Math.max(0,x))];
    p[y]=s/n;
  }
  return p;
}
/* Column profile of vertical EDGE energy, not mean brightness. The scale
   ticks and the tube walls are edges and stay put; mean brightness is
   dominated by shadows and reflections, which move with the light. Measured
   2026-08-16 on the same frame: edges matched the reference at 8 px with
   quality 0.90, brightness saturated the search at 60 px with quality 0.14
   and dragged the bands right off the tube. */
function colProfile(ff,y1,y2){
  const p=new Float32Array(W), n=y2-y1;
  for(let x=0;x<W;x++){
    let s=0;
    for(let y=y1+1;y<y2;y++) s+=Math.abs(ff[y*W+x]-ff[(y-1)*W+x]);
    p[x]=s/n;
  }
  return p;
}
/* Shared 1D alignment: best integer shift by cross-correlation, refined to
   sub-pixel with a parabola, plus a normalised match quality.

   The quality is normalised by the energy of the window that was actually
   correlated — a[i+bi], not a[i] — so it is a true cosine and never above 1.
   Until 1.14.7 it used the unshifted window, and a frame sitting several px
   off scored above 1 by an amount that differed per reference: in the
   EverFlo's 10-19 pose 'natt2' won the evening at 1.06-1.10 over natt3's ~1.0
   and said "Osäker" (see 'kväll3' under 2026-10-21 in CLAUDE.md), and it loosened the 0.75
   gate itself — a wrong-pose kitchen frame scored 0.77 where it is 0.62-0.68,
   refused only by dy, by half a pixel. It also decides the tilt (TILT_MARGIN
   compares these scores), which is why one Platinum kitchen frame, read only
   at a tilt the inflated score preferred, is refused now (its ALLOW_REFUSED). */
function align(a,b,span,i0,i1){
  let best=-1e18, bi=0; const vals={};
  for(let d=-span;d<=span;d++){
    let s=0;
    for(let i=i0;i<i1;i++){ const j=i+d; if(j<0||j>=a.length) continue; s+=a[j]*b[i]; }
    vals[d]=s; if(s>best){ best=s; bi=d; }
  }
  let na=0,nb=0;
  for(let i=i0;i<i1;i++){ const j=i+bi; if(j<0||j>=a.length) continue; na+=a[j]*a[j]; nb+=b[i]*b[i]; }
  let d=bi;
  if(vals[bi-1]!==undefined&&vals[bi+1]!==undefined){
    const den=vals[bi-1]-2*vals[bi]+vals[bi+1];
    if(Math.abs(den)>1e-9) d=bi-0.5*(vals[bi+1]-vals[bi-1])/den;
  }
  return {shift:d, quality:best/(Math.sqrt(na*nb)+1e-9)};
}
function centre(p){ let m=0; for(const v of p) m+=v; m/=p.length;
  const q=new Float32Array(p.length); for(let i=0;i<p.length;i++) q[i]=p[i]-m; return q; }
function smooth(p,w){
  const r=(w-1)/2, out=new Float32Array(p.length);
  for(let i=0;i<p.length;i++){ let s=0;
    for(let k=-r;k<=r;k++) s+=p[Math.min(p.length-1,Math.max(0,i+k))];
    out[i]=s/w; }
  return out;
}

/* ---------- reference image ---------- */
/* One place that knows what a reference contains. loadRef() uses it in the
   browser and tools/validate_engine.mjs uses it in Node, so a new field can
   never be set in one path and forgotten in the other. It reads the LIVE
   preset's geometry, so build a preset's references with that preset live. */
function buildRef(ff){
  return {ff,
          ball:    bandProfile(ff, XL, XR, BASE_TILT),
          anchor:  centre(bandProfile(ff, AX1, AX2, BASE_TILT)),
          anchorX: centre(colProfile(ff, RY1, RY2))};
}
function loadFlat(srcPng){
  return new Promise((res,rej)=>{
    const im=new Image();
    im.onload=()=>{
      const c=document.createElement('canvas'); c.width=W; c.height=H;
      const x=c.getContext('2d',{willReadFrequently:true});
      x.drawImage(im,0,0,W,H);
      res(flatfield(toGray(x.getImageData(0,0,W,H))));
    };
    im.onerror=()=>rej(new Error('Reference image failed to decode'));
    im.src=srcPng;
  });
}
/* Builds the live preset's references, once per preset. The images decode
   asynchronously and the admin page may switch preset in the meantime, so the
   build itself runs synchronously afterwards with THIS preset live — building
   against whatever happened to be live when the last image arrived would bake
   one machine's bands into another machine's reference. */
function loadRef(){
  const id=PRESET;
  if(id===null) return Promise.reject(new Error('No concentrator preset: call usePreset() first'));
  if(REF_CACHE[id]){ REFS=REF_CACHE[id]; return Promise.resolve(); }
  const pngs=PRESETS[id].refs();
  return Promise.all(pngs.map(([png])=>loadFlat(png))).then(ffs=>{
    const live=PRESET;
    usePreset(id);
    REF_CACHE[id]=ffs.map((ff,i)=>[buildRef(ff), pngs[i][1]]);
    usePreset(live);
  });
}
/* For the Node harnesses, which have no Image: they decode the PNGs themselves,
   build with buildRef() under the live preset, and hand the list in here. */
function setRefs(list){
  if(PRESET===null) throw new Error('No concentrator preset: call usePreset() first');
  REF_CACHE[PRESET]=list; REFS=list;
}

/* ---------- analysis ---------- */
/* opts overrides what the registration would otherwise measure: {dx, tilt}.
   The control panel offers both, because a human who can see the tube beats
   a correlation objective — and when the scene has changed enough that the
   correlation finds no good match at all, it beats it by a mile. */
function analyze(imgData, opts){
  const forceTilt = opts && typeof opts.tilt==='number' ? opts.tilt : undefined;
  const forceDx   = opts && typeof opts.dx  ==='number' ? opts.dx   : undefined;
  if(PRESET===null) throw new Error('No concentrator preset: call usePreset() first');
  /* A machine with no calibration yet. Every field a page shows is present so
     nothing downstream trips on it, and judge() refuses on `uncalibrated`
     before it looks at any of them. */
  if(!CAL)
    return {uncalibrated:true, y:NaN, peak:0, margin:0, reg:0, regx:0, dy:0, dx:0,
            tilt:0, flow:NaN, spread:0, profile:new Float32Array(H),
            ref:null, fallback:false, preset:PRESET};
  if(!REFS.length) throw new Error('References not built: call loadRef() first');
  const ff=flatfield(toGray(imgData));
  /* Three lighting regimes, one geometry. The kitchen is lit by the WS2812
     alone at night, by daylight through the window by day, and by low sun
     plus a rising LED share in the evening — and a reference is bound to its
     lighting. The first daylit morning (2026-08-23) took registration from
     0.98 to 0.60 against the night reference while the ball sat plainly at
     the same y; the evenings did a quieter version of the same thing.

     So the frame is analysed against every reference and the winner is
     whichever REGISTERS best: registration is the one signal the ball
     detector downstream cannot game, which is the same reason it is the tilt
     search's objective. The result carries the reference's name ('hall', 'natt', ...) so a
     human can see which regime answered.

     Cost is one extra registration search per reference per frame — the
     flatfield, which dominates, is computed once and shared. Measured over
     482 frames (23-frame night sweep + two upload corpora): every corpus
     gains or holds, none loses a frame, and no reading moves more than
     0.10 L/min. */
  const tried=[];
  for(const [R,name] of REFS)
    tried.push([analyzeWith(R, ff, forceTilt, forceDx), name]);
  tried.sort((a,b) => b[0].reg - a[0].reg);

  /* If the best-registering reference REFUSES, ask the next best, and so on.
     Selection is unchanged for every frame that produces a reading: the best
     registration still answers, and nothing here can override a reading it
     already gave. The fallback only ever turns a refusal into a reading.

     Why it is needed. Registration is measured on the ANCHOR band — the scale
     ticks — while the ball band is 20 px away at the foot of the tube, where
     the LED sits. The two are decoupled, so a reference can match the ticks
     best by a thousandth and still be wrong about the foot. Measured at dawn
     on 2026-08-30: frame 2386 had night 0.901 against day 0.897 and read
     1.61; frame 2387, fifteen minutes later, had night 0.899 against day
     0.900 and was refused — while day refused EVERY frame in that window and
     night read all of them. A thousandth of registration decided between a
     reading and a refusal, and the losing reference had the answer.

     Each fallback still passes every gate on its own — judge() is the same
     function the caller will run — so no gate is loosened. What IS loosened is
     the system: a frame that must be refused now has to be refused three times
     instead of once, so the false-accept surface is as wide as the reference list
     (five on the Platinum since 1.13.0).

     That is measurable, and the 78 wrong-pose frames in
     test/negative-old-poses/ measure it: all 78 enter this loop, none is
     rescued, and the highest registration any non-top reference reaches is
     0.664 against the 0.75 gate. (Two of the 78 have a top reference ABOVE
     the reg gate, refused by ambiguity and spread, so for those the other two
     references really are judged on all five gates.) What that set cannot
     speak for is an occlusion or a garbage frame, which are not built yet —
     see the Testing section of CLAUDE.md.

     Measured: 2026-08-22..09-05, 40 refusals -> 7; 09-05..09-11, 26 -> 9, and
     all 9 of those are one hour with a second lamp lit. No new refusals in
     either corpus, no existing reading moved, and every rescued reading
     agrees with its press span or with the signed turn the device logged. */
  /* ...but only from a reference that registers NEARLY AS WELL. The case the
     fallback exists for is a near-tie: the dawn frames above were a
     thousandth apart, and the eight EverFlo rescues stored under engine
     e3a28634 were 0.008-0.037 apart. A reference that registers clearly worse
     is the wrong lighting, and a wrong lighting can pass every gate while
     reading a broad shadow as the ball: on 2026-09-29 at dusk, with the
     Platinum switched off and the ball at rest, 'kväll' registered 0.92-0.94
     and refused (contrast 0.07-0.10), and 'dag' at 0.84-0.86 answered 1.42-
     1.65 L/min through this loop, every gate green. Gap 0.08-0.09. A refusal
     there is right; the number was not. */
  let best=tried[0][0], bestName=tried[0][1], fallback=false;
  if(!judge(best).ok){
    for(let i=1;i<tried.length;i++){
      if(tried[0][0].reg-tried[i][0].reg > FALLBACK_REG_GAP) break;   // sorted: the rest are further off
      if(judge(tried[i][0]).ok){ best=tried[i][0]; bestName=tried[i][1]; fallback=true; break; }
    }
  }
  best.ref=bestName;
  /* Stored with the reading, not just computed: a value from a reference that
     did NOT register best is the first thing to look at when one sits a few
     hundredths off its neighbours, and that question gets asked months later
     from the admin table rather than live. cleanQuality() in the admin Worker
     whitelists both this and `ref` for exactly that. */
  best.fallback=fallback;
  best.preset=PRESET;
  return best;
}
function analyzeWith(R, ff, forceTilt, forceDx){

  // Horizontal registration FIRST. The camera slides sideways (measured 34 px
  // on 2026-08-16) and everything below samples fixed x bands, so without
  // this the anchor band lands on the housing and dy is meaningless.
  const hx=align(centre(colProfile(ff,RY1,RY2)), R.anchorX, SEARCH, 60, 420);
  const dx=forceDx!==undefined ? forceDx : hx.shift;
  const regx=hx.quality, xo=Math.round(dx);

  // Tilt, then vertical registration. Both come out of the same search: the
  // tilt that makes the scale ticks match the reference best is the one the
  // camera actually has. Registration quality is the objective on purpose —
  // it measures how well the scene matches and cannot be gamed by the ball
  // detector downstream, the way optimising for a clean peak could.
  // Everything here is relative to BASE_TILT: the search is centred on it, and
  // opts.tilt overrides the DEVIATION, not the absolute angle. So 0 means "as
  // calibrated" everywhere a tilt is shown or entered, which is the only
  // reading that tells the operator whether the camera has moved.
  let hy=null, tilt=BASE_TILT, hBase=null;
  const candidates = (typeof forceTilt==='number')
    ? [BASE_TILT+forceTilt] : TILTS.map(t=>BASE_TILT+t);
  for(const t of candidates){
    const h=align(centre(bandProfile(ff,AX1+xo,AX2+xo,t)), R.anchor, SEARCH, 40, 600);
    if(t===BASE_TILT) hBase=h;
    if(!hy || h.quality>hy.quality){ hy=h; tilt=t; }
  }
  /* The calibrated tilt unless another is CLEARLY better. The anchor is
     horizontal ticks, which pin a tilt weakly: on the Platinum the search
     stepped 1-2 degrees off for a registration gain of 0.001-0.022, the
     sheared band ran onto the ticks near the top, and a steady 3.8 L/min
     flickered to "Osäker" (2026-09-30, 16:10) — the third time in two days
     after the kitchen evening and night sweeps. A camera that has really
     tipped registers clearly better at its tilt, and still gets it.
     Only the READING moves to the base tilt: `reg` stays the best over all
     tilts, because it also ranks the references and decides whether a second
     one may answer. Taking the base tilt's lower value there let the wrong
     lighting win — night frames turned 1.25 degrees read 1.64 for a true 2
     through 'dag' (review of 1.12.14). */
  const regBest=hy.quality;
  if(typeof forceTilt!=='number' && hBase && tilt!==BASE_TILT && hy.quality-hBase.quality<TILT_MARGIN){
    hy=hBase; tilt=BASE_TILT;
  }
  const dy=hy.shift, reg=regBest;

  // difference profile, shift compensated
  const pf=bandProfile(ff,XL+xo,XR+xo,tilt);
  let d=new Float32Array(H);
  for(let y=0;y<H;y++){
    const s=y+dy, i0=Math.floor(s), f=s-i0;
    const a=pf[Math.min(H-1,Math.max(0,i0))], b=pf[Math.min(H-1,Math.max(0,i0+1))];
    d[y]=Math.max(0, R.ball[y]-(a*(1-f)+b*f));
  }
  d=smooth(d,21);
  for(let y=0;y<H;y++) if(y<YTOP||y>=YBOT) d[y]=0;

  let yp=0; for(let y=0;y<H;y++) if(d[y]>d[yp]) yp=y;
  const peak=d[yp];

  let sw=0, sy=0;
  for(let y=Math.max(0,yp-35);y<Math.min(H,yp+35);y++){
    const w=Math.max(0,d[y]-0.35*peak); sw+=w; sy+=w*y;
  }
  const ycog=sw>1e-9? sy/sw : yp;

  let p2=0, y2=-1; for(let y=0;y<H;y++) if(Math.abs(y-yp)>60 && d[y]>p2){ p2=d[y]; y2=y; }
  const margin=peak/Math.max(p2,1e-9);
  /* Where the rival is, for her page's "Osäker … eller …" (1.14.3) — display
     only, nothing above or below depends on it. Measured the way the ball is
     (centroid over ±35 rows above 0.35 of its peak, the ball's own ±60 rows
     excluded), not as the argmax row: a peak row on a broad blob sits up to
     0.6 L/min off on the Platinum. And only when the rival is a real peak:
     a tail clipped at the window's edge, or the ball's own shoulder just past
     60 rows, is not a candidate, so none is offered (rivalY -1). */
  let rivalY=-1;
  if(y2>YTOP && y2<YBOT-1 && d[y2]>=d[y2-1] && d[y2]>=d[y2+1]){
    let rw=0, ry=0;
    for(let y=Math.max(0,y2-35);y<Math.min(H,y2+35);y++){
      if(Math.abs(y-yp)<=60) continue;
      const w=Math.max(0,d[y]-0.35*p2); rw+=w; ry+=w*y;
    }
    rivalY=rw>1e-9? ry/rw : y2;
  }

  let spread=0; for(let y=0;y<H;y++) if(d[y]>0.3*peak) spread++;

  const flow=CAL[0]*ycog*ycog + CAL[1]*ycog + CAL[2];
  return {y:ycog, peak, margin, reg, regx, dy, dx, rivalY,
          tilt: tilt-BASE_TILT,          // deviation from calibration, not absolute
          flow, spread, profile:d};
}

/* ---------- judgement (text stays Swedish: the operator reads it) ---------- */
/* What a candidate row would say, through the same states judge() uses. */
function candidate(y){
  if(!(y>=0)) return null;
  if(y < Y_MAX_STATE) return {label:MAX_LABEL};
  const flow=CAL[0]*y*y + CAL[1]*y + CAL[2];
  if(flow < LOW_FLOW) return {label:LOW_LABEL};
  return {label:flow.toFixed(1), flow};
}
function judge(r){
  if(r.uncalibrated)
    return {ok:false, title:"Ingen avläsning",
            reason:"Avläsningen är inte kalibrerad för den här koncentratorn än. Läs av bilden."};
  if(r.reg < T.reg)
    return {ok:false, title:"Ingen avläsning",
            reason:"Bilden matchar inte referensen. Kontrollera att kameran ser röret och att inget skymmer sikten."};
  /* Before contrast and ambiguity since 1.13.0: a camera that has moved too
     far also leaves rivals in the difference profile, and "två lika starka
     kandidater" then named the symptom instead of the cause. The registration
     test stays first — when the frame does not match at all, dx is noise. */
  if(Math.abs(r.dy) > SHIFT_Y || Math.abs(r.dx) > SHIFT_X)
    return {ok:false, title:"Ingen avläsning",
            reason:"Kameran har flyttat sig för mycket ("+r.dx.toFixed(0)+" px i sidled, "+
                   r.dy.toFixed(0)+" px i höjd). Rikta om den eller gör om kalibreringen."};
  if(r.peak < T.contrast)
    return {ok:false, title:"Ingen avläsning",
            reason:"Bollen syns inte tillräckligt tydligt. Kan bero på imma, smuts på linsen eller för svag belysning."};
  /* The one refusal that names what it saw (1.14.3, the operator's call):
     two candidates, the stronger first, so her page can say "Osäker" and show
     both — the stronger one large. Still ok:false. It is not a reading: on
     the Platinum's frames 6741-6747 the WEAKER candidate was the ball, which
     is why it is shown as a pair and never as one number. Only this gate:
     registration, shift and contrast refusals mean nothing was measured. */
  if(r.margin < T.margin)
    return {ok:false, title:"Osäker avläsning",
            reason:"Två lika starka kandidater i röret — går inte att avgöra vilken som är bollen.",
            candidates:[candidate(r.y), candidate(r.rivalY)].filter(Boolean)};
  if(r.spread > T.spread)
    return {ok:false, title:"Osäker avläsning",
            reason:"Störningen i röret är för utbredd för att vara bollen. Kontrollera att inget hänger framför röret."};
  if(r.y < Y_MAX_STATE)
    return {ok:true, maxState:true, title:null, label:MAX_LABEL, unit:MAX_UNIT,
            reason:MAX_REASON};
  /* Test what the label claims. This was a threshold on y (Y_CAL_MAX+12 = 439)
     until 2026-08-17, and the bottom of the tube is exactly where the ball
     rests when the machine is off — so the only hard boundary in judge() sat
     on top of the device's most common state. Two frames of a switched-off
     concentrator, taken 15 minutes apart and identical to the eye, came out at
     y 439.0598 and 438.9691: one said "Under 0,3", the other printed 0.16.
     Nine hundredths of a pixel, which is noise, not movement.
     Worse, 0.16 should never have been printed at all — it is past Y_CAL_MAX,
     so it is extrapolated, and it means the same thing as the label it was
     alternating with.
     On flow the boundary lands at y=430.5, some 8.5 px from where the ball
     actually rests (seen at 435 and 439), which is a margin rather than a
     coin toss. The labelled 0.3 frame reads 0.355 and still prints a number,
     so the sweep keeps checking it numerically. */
  if(r.flow < LOW_FLOW)
    return {ok:true, bottomState:true, title:null, label:LOW_LABEL,
            reason:LOW_REASON};
  if(r.y < Y_CAL_MIN-2 || r.y > Y_CAL_MAX+2)
    return {ok:true, extrapolated:true, title:null,
            reason:"Bollen står utanför det kalibrerade området — värdet är extrapolerat och mindre tillförlitligt."};
  return {ok:true, extrapolated:false, title:null,
          reason:"Inom kalibrerat område."};
}
export {toGray,flatfield,buildRef,analyze,judge,usePreset,setRefs,isCalibrated,PRESETS,W,H};
export const ENGINE_VERSION = "967ad5a";
